"""Decide which files in a project tree are excluded by its .packignore files.

This is a pure-Python reimplementation of `packignore`, the legacy exclusion
engine. It reproduces packignore's actual behaviour, which differs from
docs/PACKIGNORE.md in several places:

- Lines are split with str.splitlines() and stripped of surrounding
  whitespace. Lines starting with ";" are comments; "#" is not special.
- "!" negates; whatever follows it is used verbatim (no further stripping).
- Only "*", "?" and "**" are wildcards. "[", "]" and "\\" are literal.
  "**" is special only as a whole path segment, where it matches zero or more
  segments (so "a/**" also matches "a" itself); elsewhere it acts like "*".
- A file's verdict is decided by the deepest path level (the file itself,
  then each enclosing directory, innermost first) matched by any pattern.
  At that level, patterns from the innermost .packignore win; within one
  file, the pattern with the most non-wildcard characters ("*", "?" and "/"
  don't count) wins, and the later pattern breaks ties.
- A .packignore inside an excluded directory is not read.

packignore extracted the tree onto a case-insensitive, normalization-
insensitive filesystem before evaluating it, so this module simulates that
too: paths that differ only by case or Unicode normalization are merged (the
first name seen is kept, the last file's contents win), and the same inputs
that made packignore fail raise PackignoreError here.
"""

import os
import re
import unicodedata

PACKIGNORE = ".packignore"
MAX_FILES = 5000
MAX_PATH_BYTES = 955


class PackignoreError(Exception):
    """The tree is one packignore refused to (or could not) evaluate."""


def ignored_files(root):
    """Return the files under `root` that its .packignore files exclude.

    Paths are relative to `root`, use "/" as the separator, and are sorted.
    Only files are listed, never directories. A `.git` directory directly
    under `root` is skipped.
    """
    tree = _load_tree(root)
    ignored = []
    _walk(tree, (), [], ignored)
    return sorted(ignored)


# --- Tree loading -----------------------------------------------------------

class _Dir:
    __slots__ = ("children",)

    def __init__(self):
        self.children = {}  # fold key -> (stored name, _Dir or source path)


def _fold(name):
    nfd = unicodedata.normalize
    return nfd("NFD", nfd("NFD", name).casefold())


def _load_tree(root):
    files = []
    for dirpath, dirnames, filenames in os.walk(root):
        if os.path.samefile(dirpath, root) and ".git" in dirnames:
            dirnames.remove(".git")
        for name in filenames:
            full = os.path.join(dirpath, name)
            if os.path.islink(full) or not os.path.isfile(full):
                continue
            files.append((os.path.relpath(full, root).replace(os.sep, "/"), full))
    if len(files) > MAX_FILES:
        raise PackignoreError(f"too many files (limit {MAX_FILES})")

    top = _Dir()
    for rel, full in files:
        try:
            size = len(rel.encode("utf-8"))
        except UnicodeEncodeError:
            raise PackignoreError(f"file name is not valid UTF-8: {rel!r}") from None
        if size > MAX_PATH_BYTES:
            raise PackignoreError(f"path too long: {rel!r}")
        *dirs, base = rel.split("/")
        node = top
        for part in dirs:
            entry = node.children.get(_fold(part))
            if entry is None:
                entry = node.children[_fold(part)] = (part, _Dir())
            elif not isinstance(entry[1], _Dir):
                raise PackignoreError(f"file/directory name clash: {rel!r}")
            node = entry[1]
        key = _fold(base)
        entry = node.children.get(key)
        if entry is None:
            node.children[key] = (base, full)
        elif isinstance(entry[1], _Dir):
            raise PackignoreError(f"file/directory name clash: {rel!r}")
        else:
            node.children[key] = (entry[0], full)
    return top


# --- Patterns ---------------------------------------------------------------

class _Pattern:
    __slots__ = ("negate", "dir_only", "anchored", "segments", "score")

    def __init__(self, negate, dir_only, anchored, segments, score):
        self.negate = negate
        self.dir_only = dir_only
        self.anchored = anchored
        self.segments = segments  # compiled regexes, or None for "**"
        self.score = score


def _compile_segment(seg):
    if seg == "**":
        return None
    out = []
    for ch in seg:
        if ch == "*":
            if not out or out[-1] != "[^/]*":
                out.append("[^/]*")
        elif ch == "?":
            out.append("[^/]")
        else:
            out.append(re.escape(ch))
    return re.compile("".join(out), re.DOTALL)


def _parse_line(line):
    line = line.strip()
    if not line or line.startswith(";"):
        return None
    negate = line.startswith("!")
    if negate:
        line = line[1:]
    score = sum(1 for ch in line if ch not in "*?/")
    dir_only = line.endswith("/")
    if dir_only:
        line = line[:-1]
    anchored = "/" in line
    if line.startswith("/"):
        line = line[1:]
    if not line:
        return None
    segments = [_compile_segment(seg) for seg in line.split("/")]
    return _Pattern(negate, dir_only, anchored, segments, score)


def _read_patterns(source):
    with open(source, "rb") as f:
        data = f.read()
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise PackignoreError(f"{PACKIGNORE} is not valid UTF-8: {source}") from None
    return [p for p in map(_parse_line, text.splitlines()) if p is not None]


def _match_segments(segs, parts):
    """Match pattern segments against path segments, "**" spanning any number."""
    memo = {}

    def go(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        if i == len(segs):
            res = j == len(parts)
        elif segs[i] is None:
            res = go(i + 1, j) or (j < len(parts) and go(i, j + 1))
        else:
            res = j < len(parts) and segs[i].fullmatch(parts[j]) is not None and go(i + 1, j + 1)
        memo[key] = res
        return res

    return go(0, 0)


def _matches(pat, parts, is_dir):
    if pat.dir_only and not is_dir:
        return False
    if pat.anchored:
        return _match_segments(pat.segments, parts)
    return _match_segments(pat.segments, parts[-1:])


# --- Evaluation -------------------------------------------------------------

def _level_verdict(rules, path, is_dir):
    """Verdict for one path level: True/False, or None if no pattern matches.

    `rules` lists (base depth, patterns) for each .packignore in effect,
    outermost first.
    """
    for base, patterns in reversed(rules):
        best = None
        for pat in patterns:
            if (best is None or pat.score >= best.score) and _matches(pat, path[base:], is_dir):
                best = pat
        if best is not None:
            return not best.negate
    return None


def _excluded(rules, path, is_dir, parent_levels):
    verdict = _level_verdict(rules, path, is_dir)
    if verdict is not None:
        return verdict
    return parent_levels


def _walk(node, path, rules, ignored, inherited=False):
    """Collect ignored files below `node`.

    `inherited` is the verdict from the deepest matched enclosing level, which
    applies when nothing matches at a deeper level.
    """
    entry = node.children.get(_fold(PACKIGNORE))
    if entry is not None and entry[0] == PACKIGNORE and not isinstance(entry[1], _Dir):
        rules = rules + [(len(path), _read_patterns(entry[1]))]
    for name, child in node.children.values():
        child_path = path + (name,)
        is_dir = isinstance(child, _Dir)
        excluded = _excluded(rules, child_path, is_dir, inherited)
        if is_dir:
            if excluded:
                _walk_excluded(child, child_path, rules, ignored)
            else:
                _walk(child, child_path, rules, ignored, excluded)
        elif excluded:
            ignored.append("/".join(child_path))


def _walk_excluded(node, path, rules, ignored):
    """Like _walk, for a directory that is excluded: its .packignore is not read."""
    for name, child in node.children.values():
        child_path = path + (name,)
        is_dir = isinstance(child, _Dir)
        excluded = _excluded(rules, child_path, is_dir, True)
        if is_dir:
            if excluded:
                _walk_excluded(child, child_path, rules, ignored)
            else:
                _walk(child, child_path, rules, ignored, excluded)
        elif excluded:
            ignored.append("/".join(child_path))

